"""
Module providing the functionality to create the emil
collector configuration for cloud gNodeB deployment.
"""
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CloudGnbEmilCollectorConfigurator:

    def add_emil(self, ne_log_name, ne_log_configuration):
        existing_dcap_collectors = self._collector_configuration_data.find_collectors(
            collector_type='log_collection_classical_gnb_emil')
        if existing_dcap_collectors:
            logger.info("collector already existing! Let's check, what we can do...")
            self._handle_existing_collector(ne_log_name, existing_dcap_collectors[0])
        else:
            logger.info("collector not existing! Let's start creating it...")
            self._add_emil_collector_group(ne_log_name)

    def _handle_existing_collector(self, ne_log_name, existing_dcap_collector):
        existing_groups = self._collector_configuration_data.find_parent_groups(
            existing_dcap_collector['name'])
        current_groups = self._collector_configuration_data.find_parent_groups(
            f"{ne_log_name}")
        if existing_groups == current_groups and len(existing_groups) == 1:
            self._add_emil_collector_to_existing_collector(existing_dcap_collector)
        else:
            raise AssertionError("Current Configuration not possible!")

    def _add_emil_collector_to_existing_collector(self, existing_dcap_collector):
        """
        Adds emil to an existing dcap collector. Only the entry for the gnb_custom_profile gets enhanced.
        """
        # TODO: The current collector name must be kept in a mapping table, so we are able to detect the
        # collector by the collector name later on.

        # find the cu emil collector configuration
        # and append the controlPlane5gVcu, if it is not there yet
        # iterate over all vdu emil collector configurations
        # append the controlPlane5gVdu to all those configurations, if it is not yet in place

    def _add_emil_collector_group(self, ne_log_name):
        # TODO: create one DcapTraceCollector with vCU and vDU profiles instead of a collector group,
        # because the former is faster

        cu_decorating_collector_name = self._add_cu_decorating_collector(ne_log_name)
        vdu_decorating_collector_names = self._add_vdu_decorating_collectors(ne_log_name)

        emil_collector_group_config = {
            'name': ne_log_name,
            'type': 'group',
            'members': [cu_decorating_collector_name] + vdu_decorating_collector_names}

        self._collector_configuration_data.append(emil_collector_group_config)

        self._collector_configuration_data.add_mapping_entry(
            log_type='emil',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=emil_collector_group_config)

    def _add_cu_decorating_collector(self, ne_log_name):
        cu_oam_config = self.tl_config_information_provider.get_cu_oam_http_connection_details(node_id=self.ne_id)
        cu_oam_config['username'] = cu_oam_config.pop('user')
        cu_oam_config.update({'password': 'Nokia@123'})

        cu_dcap_collector_name = self._add_cu_dcap_collector(cu_oam_config)
        cu_decorating_collector_name = f'{ne_log_name}_decorating_cu'
        self._collector_configuration_data.append(
            {
                'name': cu_decorating_collector_name,
                'type': 'log_collection_cloud_gnb_emil',
                'collector': cu_dcap_collector_name,
                'oam_config': cu_oam_config,
                'cloud_part': 'cu',
                'executor': {
                    'type': 'local'}})  # TODO: also support remote DCAPs for multiple gNBs
        return cu_decorating_collector_name

    def _add_cu_dcap_collector(self, cu_oam_config):
        cu_dcap_collector_name = f'dcap_{self.ne_type}_{self.ne_id}_cu'
        self._collector_configuration_data.append(
            {
                'name': cu_dcap_collector_name,
                'type': 'dcap',
                'trace': {
                    'bts': cu_oam_config,
                    'vcu_custom_profile': ['controlPlane5gVcu']}})
        return cu_dcap_collector_name

    def _add_vdu_decorating_collectors(self, ne_log_name):
        return [
            self._add_vdu_decorating_collector(ne_log_name, vdu_id)
            for vdu_id in self.tl_config_information_provider.get_du_ids(node_id=self.ne_id)]

    def _add_vdu_decorating_collector(self, ne_log_name, vdu_id):
        vdu_oam_config = self.tl_config_information_provider.get_vdu_oam_http_connection_details(
            node_id=self.ne_id,
            vdu_id=vdu_id)
        vdu_oam_config['username'] = vdu_oam_config.pop('user')
        vdu_oam_config.update({'password': 'Nokia@123'})

        vdu_dcap_collector_name = self._add_vdu_dcap_collector(vdu_id, vdu_oam_config)
        vdu_decorating_collector_name = f'{ne_log_name}_decorating_vdu_{vdu_id}'
        self._collector_configuration_data.append(
            {
                'name': vdu_decorating_collector_name,
                'type': 'log_collection_cloud_gnb_emil',
                'collector': vdu_dcap_collector_name,
                'oam_config': vdu_oam_config,
                'cloud_part': 'vdu',
                'executor': {
                    'type': 'local'}})  # TODO: also support remote DCAPs for multiple gNBs
        return vdu_decorating_collector_name

    def _add_vdu_dcap_collector(self, vdu_id, vdu_oam_config):
        vdu_dcap_collector_name = f'dcap_{self.ne_type}_{self.ne_id}_vdu_{vdu_id}'
        self._collector_configuration_data.append(
            {
                'name': vdu_dcap_collector_name,
                'type': 'dcap',
                'trace': {
                    'bts': vdu_oam_config,
                    'vdu_custom_profile': ['controlPlane5gVdu']}})
        return vdu_dcap_collector_name
